<script setup lang="ts">import { inject } from 'vue'; import type { TraceGlow } from '@trace-glow/vue'; const telemetry = inject<TraceGlow>('trace-glow')!; const log = () => telemetry.logger.info('demo.vue.log'); const fail = () => { throw new Error('Vue demo error'); }; const fetchPage = () => fetch(window.location.href, { cache: 'no-store' }); const createSpan = () => telemetry.client.startSpan('demo.vue.action').setStatus('ok').end();</script><template><main><h1>Vue demo</h1><p>Web Vitals, browser performance entries, Fetch, XHR, and error instrumentation are enabled.</p><button @click="log">Capture log</button><button @click="createSpan">Create span</button><button @click="fetchPage">Fetch page</button><button @click="fail">Trigger Vue error</button></main></template>
